// Command gensample writes the recorded DJI-format sample used when live DJI
// access is unavailable (R-02) and as the demo/replay source:
//
//	go run ./cmd/gensample -out testdata/dji_sample.csv
//
// The file is SIMULATED data (generated by the mock feed, not recorded from a
// real aircraft). The demo must say so. If you later capture a real DJI log,
// export it with the same column names and drop it in instead.
package main

import (
	"context"
	"flag"
	"log"
	"os"
	"time"

	"github.com/omarzayedbeshir/drone-fleet-management/internal/mockfeed"
	"github.com/omarzayedbeshir/drone-fleet-management/internal/vendor"
)

func main() {
	out := flag.String("out", "testdata/dji_sample.csv", "output file")
	drones := flag.Int("drones", 3, "number of drones")
	rounds := flag.Int("rounds", 40, "samples per drone")
	flag.Parse()

	ids := make([]string, *drones)
	for i := range ids {
		ids[i] = "SIM-DJI-" + string(rune('A'+i)) + "001"
	}
	// Deterministic clock: every call advances 500 ms.
	t := time.Date(2026, 10, 20, 9, 0, 0, 0, time.UTC)
	now := func() time.Time { t = t.Add(500 * time.Millisecond); return t }

	feed := mockfeed.New(mockfeed.Config{DroneIDs: ids, Seed: 42, Now: now, MaxRecords: *drones * *rounds})
	ch := make(chan vendor.RawRecord, *drones**rounds)
	if err := feed.Subscribe(context.Background(), ch); err != nil {
		log.Fatal(err)
	}
	close(ch)
	var recs []vendor.RawRecord
	for r := range ch {
		recs = append(recs, r)
	}

	f, err := os.Create(*out)
	if err != nil {
		log.Fatal(err)
	}
	defer f.Close()
	if err := mockfeed.WriteCSV(f, recs); err != nil {
		log.Fatal(err)
	}
	log.Printf("wrote %d rows to %s", len(recs), *out)
}
